package com.library.entity.enums;

/**
 * Types of in-app notifications generated by the borrow/delivery workflow.
 */
public enum NotificationType {
    NEW_PHYSICAL_REQUEST,  // To library admins: a new physical borrow request arrived
    PHYSICAL_APPROVED,     // To user: physical borrow request approved
    PHYSICAL_REJECTED,     // To user: physical borrow request rejected
    BOOK_DISPATCHED,       // To user: a courier has been assigned to deliver the book
    RECEIPT_CONFIRMED,     // To admin: user confirmed receiving the book
    RETURN_DUE,            // To user: loan period ended, please return the book
    RETURN_CONFIRMED,      // To user: librarian recorded the book as returned
    BORROW_CANCELLED_BY_USER,      // To admins: the recipient cancelled the request/loan
    BORROW_CANCELLED_BY_LIBRARIAN, // To user: the librarian cancelled the request/loan
    RETURN_REQUESTED,              // To admins: the recipient asked for a return pickup
    RETURN_PICKUP_SCHEDULED,       // To user: the librarian scheduled the return pickup
    BOOK_HANDED_OVER               // To admins: the recipient handed the book to the courier (in transit)
}
